package com.bejo.commerce.dto;

import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * Batch of manually-added transactions pushed by the client when it comes back
 * online after offline entry. Each item carries its own {@code idempotencyKey}
 * (generated by the client when the record was created offline) so re-syncing the
 * whole batch — or a partial batch after a dropped connection — never duplicates.
 *
 * <p>Items are NOT bean-validated by the container (the element type is left
 * un-cascaded on purpose); the service validates each item individually so a single
 * malformed row fails on its own instead of rejecting the whole batch.
 */
public record BulkAddTransactionRequestDto(
        @NotEmpty(message = "transactions tidak boleh kosong")
        @Size(max = 500, message = "maksimal 500 transaksi per batch")
        List<BulkTransactionItemDto> transactions
) {}
